const m = $json;
const health = Number(m.dead_queue_count || 0) > 0 ? 'ATTENTION REQUIRED' : Number(m.open_errors || 0) > 0 ? 'MONITOR' : 'HEALTHY';
const breakdown = typeof m.application_status_breakdown === 'string' ? JSON.parse(m.application_status_breakdown) : (m.application_status_breakdown || {});
const statusLines = Object.entries(breakdown).sort(([a], [b]) => a.localeCompare(b)).map(([status, total]) => `- ${status}: ${total}`).join('
') || '- No application records';
const reportDate = new Date(m.generated_at || Date.now()).toISOString();
const email = `NovaTech Solutions - Daily Recruitment Operations Report
Generated: ${reportDate}
System health: ${health}

APPLICATIONS
Total candidates: ${m.candidates_total}
Total applications: ${m.applications_total}
Applications today: ${m.applications_today}
Manual review: ${m.manual_review_count}
Shortlisted: ${m.shortlisted_count}

APPLICATION STATUS BREAKDOWN
${statusLines}

INTERVIEWS
Pending confirmations: ${m.pending_interview_confirmations}
Pending feedback: ${m.pending_interview_feedback}

OFFERS
Pending approvals: ${m.pending_offer_approvals}
Pending candidate responses: ${m.pending_candidate_offers}
Expired offers: ${m.expired_offers}

ONBOARDING
Employees onboarding: ${m.employees_onboarding}
Overdue onboarding tasks: ${m.overdue_onboarding_tasks}

ERROR AND RECOVERY
Open errors: ${m.open_errors}
Retrying errors: ${m.retrying_errors}
Dead queue: ${m.dead_queue_count}
Resolved today: ${m.errors_resolved_today}

EXECUTIONS
Executions today: ${m.executions_today}
Successful: ${m.successful_executions_today}
Failed/dead: ${m.failed_executions_today}
Retries: ${m.retries_today}
Average application processing seconds: ${m.average_application_processing_seconds}

NovaTech Solutions Automation`;
return [{ json: { ...m, system_health: health, report_generated_at: reportDate, report_recipient: 'itxtaha77@gmail.com', email_subject: `NovaTech Daily Operations Report - ${reportDate.slice(0, 10)}`, email_message: email } }];

const m = $json;
const dead = Number(m.dead_queue_count || 0);
const open = Number(m.open_errors || 0);
const overdue = Number(m.overdue_onboarding_tasks || 0);
const health = dead > 0 ? 'ATTENTION_REQUIRED' : open > 0 || overdue > 0 ? 'MONITOR' : 'HEALTHY';
return [{ json: { success: true, generated_at: m.generated_at, system_health: health, summary: { candidates_total: m.candidates_total, applications_total: m.applications_total, applications_today: m.applications_today, manual_review_count: m.manual_review_count, pending_interview_confirmations: m.pending_interview_confirmations, pending_interview_feedback: m.pending_interview_feedback, pending_offer_approvals: m.pending_offer_approvals, pending_candidate_offers: m.pending_candidate_offers, expired_offers: m.expired_offers, employees_onboarding: m.employees_onboarding, overdue_onboarding_tasks: m.overdue_onboarding_tasks, open_errors: m.open_errors, retrying_errors: m.retrying_errors, dead_queue_count: m.dead_queue_count, errors_resolved_today: m.errors_resolved_today, executions_today: m.executions_today, successful_executions_today: m.successful_executions_today, failed_executions_today: m.failed_executions_today, retries_today: m.retries_today, average_application_processing_seconds: m.average_application_processing_seconds }, application_status_breakdown: m.application_status_breakdown, display_status: 'Operational Dashboard Metrics Loaded' } }];
